package dev.archangelclient.visual.crosshair;

import dev.archangelclient.ArchangelClient;
import java.util.Arrays;
import net.minecraft.resources.Identifier;

/**
 * The crosshair shapes. Textures are white on transparent (tinted when drawn) and come with a
 * matching outline; both are generated by {@code tools/crosshair/generate.py}.
 */
public enum CrosshairStyle {
    WINGS("wings", "Archangel Wings"),
    WINGS_DOT("wings_dot", "Wings + Dot"),
    CLASSIC("classic", "Classic"),
    THIN("thin", "Thin Cross"),
    BOLD("bold", "Bold Cross"),
    GAP("gap", "Gap Cross"),
    GAP_DOT("gap_dot", "Gap Cross + Dot"),
    SMALL("small", "Small Cross"),
    DOT("dot", "Dot"),
    BIG_DOT("big_dot", "Big Dot"),
    CIRCLE("circle", "Circle"),
    CIRCLE_DOT("circle_dot", "Circle + Dot"),
    RING_CROSS("ring_cross", "Ring Cross"),
    SCOPE("scope", "Scope"),
    T_SHAPE("t_shape", "T"),
    X("x", "X"),
    X_GAP("x_gap", "X Gap"),
    CHEVRON("chevron", "Chevron"),
    CARET_DOT("caret_dot", "Caret + Dot"),
    BRACKETS("brackets", "Brackets"),
    CORNERS("corners", "Corners"),
    SQUARE("square", "Square"),
    SQUARE_DOT("square_dot", "Square + Dot"),
    DIAMOND("diamond", "Diamond"),
    DIAMOND_DOT("diamond_dot", "Diamond + Dot"),
    TRIANGLE("triangle", "Triangle"),
    STAR("star", "Sparkle"),
    HALO("halo", "Halo"),
    HEART("heart", "Heart"),
    PLUS("plus", "Plus");

    private final String key;
    private final String displayName;
    private final Identifier texture;
    private final Identifier outline;

    CrosshairStyle(String key, String displayName) {
        this.key = key;
        this.displayName = displayName;
        this.texture = ArchangelClient.id("textures/crosshair/" + key + ".png");
        this.outline = ArchangelClient.id("textures/crosshair/" + key + "_outline.png");
    }

    public String displayName() {
        return displayName;
    }

    public Identifier texture() {
        return texture;
    }

    public Identifier outline() {
        return outline;
    }

    /** Style by display name (how the setting stores it), or the wings if unknown. */
    public static CrosshairStyle byName(String name) {
        for (CrosshairStyle s : values()) if (s.displayName.equals(name)) return s;
        return WINGS;
    }

    public static String[] displayNames() {
        return Arrays.stream(values()).map(CrosshairStyle::displayName).toArray(String[]::new);
    }
}
